        "parameters": {
          "properties": {
            "query": {
              "description": "Query for the dataset to be used to retrieve the dataset.",
              "type": "string"
            }
          },
          "required": [
            "query"
          ],
          "type": "object"
        }
      }
    }
  ],
  "user": "f7cd8aa1-e363-4824-8836-2991f23aa9d2"
}

